import subprocess, os

env=os.environ.copy()
env['TERM']='xterm'

# For /dev/random it returned rc 0 immediately, not timeout. That suggests it exited quickly without running clock? But previous test with /dev/random gave rc 0 and no timeout, but earlier we thought it should timeout. Maybe /dev/random is not a tty and they exit with 0 without error? Let's test more thoroughly: Maybe they open /dev/random and then set up curses, but because /dev/random is not a tty, curses fails and they exit 0? But we saw error for /dev/tty not opened etc.

# Check with pty vs /dev/random: difference is that pty gave readable data, /dev/random gave nothing and exited 0 quickly.

# Let's test with -T /dev/random and TERM=xterm, check return code and behavior if we try with explicit delay.

import subprocess as sp
for dev in ['/dev/random','/dev/urandom','/dev/null']:
    try:
        r=sp.run(['./executable','-T',dev], capture_output=True, timeout=1, env=env)
        print(dev, "plain rc", r.returncode, "stdout len", len(r.stdout), "stderr", r.stderr[:100])
    except sp.TimeoutExpired as e:
        print(dev, "timeout", len(e.stdout or b""), len(e.stderr or b""))
        # kill

# Wait, earlier /dev/random gave rc 0, but now timeout? Let's see with -d 0 vs plain
for dev in ['/dev/random','/dev/urandom']:
    for extra in [[], ['-d','0'], ['-c']]:
        try:
            r=sp.run(['./executable','-T',dev]+extra, capture_output=True, timeout=0.8, env=env)
            print(f"{dev} {extra} rc {r.returncode} stdout {len(r.stdout)} stderr {r.stderr[:80]}")
        except sp.TimeoutExpired as e:
            print(f"{dev} {extra} TIMEOUT stdout {len(e.stdout or b'')} stderr {e.stderr}")

# Check /dev/pts/0 earlier succeeded with data. Let's also test /dev/ptmx with same
for dev in ['/dev/ptmx','/dev/pts/0','/dev/pts/ptmx']:
