import os, termios

# Interesting: /dev/random and /dev/urandom give EINVAL (22) vs ENOTTY (25) for others.
# That suggests kernel treats them differently: random/urandom may have different ioctl handling.

# Let's see errno values: 25 ENOTTY, 22 EINVAL. So random returns EINVAL for tcgetattr, while null/zero/full return ENOTTY.

# Could tty-clock be checking tcgetattr and if it fails with EINVAL treat as error and exit 0?
# But for null it still hangs, so they don't exit even if tcgetattr fails with ENOTTY.

# Wait ptmx succeeds with tcgetattr, and it hangs (as expected for terminal).

# Let's test other devices that return EINVAL vs ENOTTY: maybe random/urandom are the only ones returning EINVAL, and tty-clock exits 0 for those.
# Check /dev/kmsg maybe returns different?

import subprocess, os

# Let's try to see if tty-clock's exit 0 for random is actually an error path that returns 0 without message.
# Could they do: if tcgetattr fails, they exit 0? But then null should also exit 0, but it hangs.

# So not.

# Let's check what happens if we run with -T /dev/random but monitor with timeout and check if process writes to that device.
# We can test by opening /dev/random as file and seeing if tty-clock writes there (it should, but we can't intercept).

# Another angle: maybe tty-clock tries to set terminal to raw mode via cbreak() etc, and for random devices, that fails and they exit?

# Let's write a C program that mimics tty-clock init: open file, newterm, then cbreak, etc, and see return codes.

code = r"""
#include <curses.h>
#include <stdio.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
int main(int argc, char *argv[]) {
    const char *dev = argv[1] ? argv[1] : "/dev/null";
    FILE *f = fopen(dev, "r+");
    if (!f) { perror("fopen"); return 1; }
    int fd = fileno(f);
    struct termios t;
    int r = tcgetattr(fd, &t);
    printf("tcgetattr %d errno %d %s\n", r, errno, strerror(errno));
    SCREEN *scr = newterm(NULL, f, f);
    printf("newterm %p\n", scr);
    if (!scr) { printf("newterm null\n"); return 0; }
    set_term(scr);
    r = cbreak();
    printf("cbreak %d\n", r);
    r = noecho();
    printf("noecho %d\n", r);
    r = nodelay(stdscr, TRUE);
    printf("nodelay %d\n", r);
    r = curs_set(0);
    printf("curs_set %d\n", r);
    // try refresh
    printw("hello");
    refresh();
    printf("refresh done\n");
    // try getch nonblock
    nodelay(stdscr, TRUE);
    int ch = getch();
    printf("getch %d ERR=%d\n", ch, ERR);
    endwin();
    delscreen(scr);
    fclose(f);
    return 0;
}
"""
open('/tmp/test3.c','w').write(code)
import subprocess, os
subprocess.run(['gcc','/tmp/test3.c','-lncurses','-o','/tmp/test3'], check=True)
for dev in ['/dev/null','/dev/random','/dev/zero','/dev/urandom','/dev/full']:
    env=os.environ.copy()
    env['TERM']='xterm'
