int clock_width() {
    int digits_count = show_seconds ? 6 : 4;
    int width = digits_count * 6;
    int gaps = show_seconds ? (3*1 + 2*6) : (2*1 + 6);
    return width + gaps;
}
int clock_height() { return 5; }

void init_colors() {
    if (!has_colors()) return;
    start_color();
    use_default_colors();
    int bg = color;
    // init_pair 1 for clock: fg black bg = color, pair 2 for date: fg = color bg = -1
    init_pair(1, COLOR_BLACK, bg);
