}

void draw_clock(WINDOW *win, int y, int x, struct tm *tm, int colon_visible) {
    int hour = tm->tm_hour;
    int minute = tm->tm_min;
    int second = tm->tm_sec;
    if (twelve_hour) {
        int is_pm = hour >= 12;
        (void)is_pm;
        hour = hour % 12;
        if (hour == 0) hour = 12;
    }
    int h1 = hour / 10;
    int h2 = hour % 10;
    int m1 = minute / 10;
    int m2 = minute % 10;
    int s1 = second / 10;
    int s2 = second % 10;

    int pos = x;
    // For 12h, hour may be single digit? Original shows leading space? Let's see earlier: for 1 AM, it showed "     ## ..." with leading blank? For 1 hour, tens digit is blank? Actually for 12h, 1 o'clock shows first digit as '1' but with leading? In our earlier capture, 1:00 in 12h? Let's check: For 00:00 in 12h, it shows 12:00 (two digits). For 01:00 in 12h, it should show " 1:00" or "01:00"? Let's see earlier: for 13:00 (1 PM) in 12h, we saw first digit was ' '?? Let's re-evaluate: For 13:00 without -t, it shows "13:00" as "     ## ###### ..." Actually 13:00 shows "     ## ###### ..." where first digit is '1' (4 wide with leading spaces) and second digit '3'. So hour is always two digits, with leading zero? For 1 AM, hour=1, 12h => 1, but display should be " 1"? Let's check earlier: For 00:00 with -t, it showed 12:00, not 00. For 13:00 with -t, it showed 01:00? Actually 13 in 24h => 1 PM, should be "01:00" or " 1:00"? Our capture for 13:00 with -t showed " ######     ##" which is digit '0' vs '1'? Hard to know. Let's just implement two-digit hour with leading zero for 24h, and for 12h, pad with space if hour<10.

    // Determine if we should pad hour tens with blank
    int hour_tens_blank = 0;
    if (twelve_hour && hour < 10) {
        // For hour <10, tens digit is blank (space)
        hour_tens_blank = 1;
    }

    // Draw h1
    if (!hour_tens_blank) {
        for (int r=0; r<5; r++) {
            for (int c=0; c<6; c++) {
                char ch = digits[h1][r][c];
                int wy = y+r, wx = pos+c;
