        fclose(tty_fp);
        tty_fp = NULL;
    }
}

int main(int argc, char *argv[]) {
    // Manual parsing to match original behavior
    char *prog = argv[0];
    // Loop
    for (int i=1; i<argc; i++) {
        char *arg = argv[i];
        if (strcmp(arg, "--") == 0) {
            // end of options, ignore rest
            break;
        }
        if (arg[0] != '-' || arg[1] == '\0') {
            // non-option, ignore
            continue;
        }
        // Handle combined flags
        for (size_t pos=1; arg[pos] != '\0'; pos++) {
            char c = arg[pos];
            switch(c) {
                case 'i':
                    print_info();
                    return 0;
                case 'v':
                    print_version();
                    return 0;
                case 'h':
                    print_usage();
                    return 0;
                case 's':
                    show_seconds = 1;
                    break;
                case 'S':
                    screensaver = 1;
                    break;
                case 'x':
                    show_box = 1;
                    break;
                case 'c':
                    centered = 1;
                    break;
                case 'b':
                    bold = 1;
                    break;
                case 't':
                    twelve_hour = 1;
                    break;
                case 'u':
                    use_utc = 1;
                    break;
                case 'r':
                    rebound = 1;
                    break;
                case 'D':
                    hide_date = 1;
                    break;
                case 'B':
                    blinking = 1;
                    break;
                case 'n':
                    no_quit = 1;
                    break;
                case 'C': {
                    char *val = NULL;
                    if (arg[pos+1] != '\0') {
                        val = &arg[pos+1];
                        pos = strlen(arg)-1;
                    } else if (i+1 < argc) {
                        val = argv[i+1];
                        i++;
                    } else {
                        fprintf(stderr, "%s: option requires an argument -- '%c'\n", prog, c);
                        print_usage();
                        return 0;
                    }
                    // parse color
                    long col = 0;
                    char *endptr;
                    col = strtol(val, &endptr, 10);
                    // If no digits found, endptr == val, then col remains 0 (as atoi would give 0)
                    // But strtol gives 0 as well. Need to distinguish: atoi("abc")=0, strtol("abc")=0 with endptr==val.
                    // For those, we should treat as 0.
                    if (endptr == val) col = 0;
                    if (col >=0 && col <=7) color = (int)col;
                    else color = 2;
                    break;
                }
                case 'f': {
                    char *val = NULL;
                    if (arg[pos+1] != '\0') {
                        val = &arg[pos+1];
                        pos = strlen(arg)-1;
                    } else if (i+1 < argc) {
                        val = argv[i+1];
                        i++;
                    } else {
                        fprintf(stderr, "%s: option requires an argument -- '%c'\n", prog, c);
                        print_usage();
                        return 0;
                    }
                    date_format = val;
                    break;
                }
                case 'd': {
                    char *val = NULL;
                    if (arg[pos+1] != '\0') {
                        val = &arg[pos+1];
                        pos = strlen(arg)-1;
                    } else if (i+1 < argc) {
                        val = argv[i+1];
                        i++;
                    } else {
                        fprintf(stderr, "%s: option requires an argument -- '%c'\n", prog, c);
                        print_usage();
                        return 0;
                    }
                    delay_sec = atol(val);
                    if (delay_sec <0) delay_sec = 0; // allow? original may allow negative but treat?
                    break;
                }
                case 'a': {
                    char *val = NULL;
                    if (arg[pos+1] != '\0') {
                        val = &arg[pos+1];
                        pos = strlen(arg)-1;
                    } else if (i+1 < argc) {
                        val = argv[i+1];
                        i++;
                    } else {
                        fprintf(stderr, "%s: option requires an argument -- '%c'\n", prog, c);
                        print_usage();
                        return 0;
                    }
                    delay_nsec = atol(val);
                    if (delay_nsec <0) delay_nsec = 0;
                    break;
                }
                case 'T': {
                    char *val = NULL;
                    if (arg[pos+1] != '\0') {
                        val = &arg[pos+1];
                        pos = strlen(arg)-1;
                    } else if (i+1 < argc) {
                        val = argv[i+1];
                        i++;
                    } else {
                        fprintf(stderr, "%s: option requires an argument -- '%c'\n", prog, c);
                        print_usage();
                        return 0;
                    }
                    tty_path = val;
                    break;
                }
                default: {
                    fprintf(stderr, "%s: invalid option -- '%c'\n", prog, c);
                    print_usage();
                    return 0;
                }
            }
        }
    }

    if (!date_format) date_format = "%Y-%m-%d";

    // Handle -T errors before curses init, and also handle term errors
    // First, handle tty_path stat and open checks
    if (tty_path) {
        struct stat st;
        if (stat(tty_path, &st) != 0) {
            fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s\n", tty_path, strerror(errno));
            return 1;
        }
        if (!S_ISCHR(st.st_mode)) {
            fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", tty_path);
            return 1;
        }
        tty_fp = fopen(tty_path, "r+");
        if (!tty_fp) {
            fprintf(stderr, "tty-clock: error: '%s' couldn't be opened: %s\n", tty_path, strerror(errno));
            return 1;
        }
    }

    // Setup signal handlers
    signal(SIGWINCH, handle_sigwinch);
    signal(SIGTERM, handle_sigterm);
    signal(SIGINT, handle_sigterm);

    // Initialize curses
    // If tty_path is set, we use newterm for that tty, else initscr
    if (tty_path) {
        // Use tty_fp for both input and output
        ttyscr = newterm(NULL, tty_fp, tty_fp);
        if (!ttyscr) {
            fprintf(stderr, "%s: ttyclock.c:%d: init: Assertion `ttyclock.ttyscr != NULL' failed.\n", prog, 53);
            abort();
        }
        set_term(ttyscr);
    } else {
        // Check TERM
        char *term = getenv("TERM");
        if (!term || term[0]=='\0') {
            fprintf(stderr, "Error opening terminal: unknown.\n");
            return 1;
        }
        // Try to open term
        // Use setupterm check
        int errret;
        // Use initscr which will handle TERM
        // But we need to detect unknown terminal
        // We'll try to init and catch error: If TERM is unknown, initscr will print "Error opening terminal: unknown." to stderr and exit?
        // Instead, we can use setupterm to check.
        // Let's use newterm with NULL
        ttyscr = newterm(NULL, stdout, stdin);
        if (!ttyscr) {
            fprintf(stderr, "Error opening terminal: %s.\n", term);
            return 1;
        }
        set_term(ttyscr);
    }

    // Now ttyscr is set
    // Check for TERM unknown via setupterm already? newterm returns NULL for unknown, we handled.
    // For valid TERM, continue

    // Initialize
    cbreak();
    noecho();
    nodelay(stdscr, TRUE);
    keypad(stdscr, TRUE);
    curs_set(0);
    if (has_colors()) {
        init_colors();
    }

    // Get initial size
    int max_y, max_x;
    getmaxyx(stdscr, max_y, max_x);
    int cw = clock_width();
    int ch = clock_height();
    int date_h = hide_date ? 0 : 1;
    int box_extra_w = show_box ? 2 : 0;
    int box_extra_h = show_box ? 2 : 0;
    int total_w = cw + box_extra_w;
    int total_h = ch + date_h + box_extra_h;
    // Position
    if (centered) {
        clock_y = (max_y - total_h) / 2;
        clock_x = (max_x - total_w) / 2;
        if (clock_y <0) clock_y =0;
        if (clock_x <0) clock_x =0;
    } else {
        clock_y = 0;
        clock_x = 0;
    }

    // Main loop
    struct timespec req;
    req.tv_sec = delay_sec;
    req.tv_nsec = delay_nsec;
    if (req.tv_sec==0 && req.tv_nsec==0) {
        // Default 1 sec if both zero? But original allows 0 delay? We should allow 0.
        // Keep as is
    }

    int blink_state = 1;
