    while (!exit_flag) {
        if (resize_flag) {
            resize_flag = 0;
            // Handle resize: clear and get new size
            endwin();
            refresh();
            getmaxyx(stdscr, max_y, max_x);
            if (centered) {
                clock_y = (max_y - total_h) / 2;
                clock_x = (max_x - total_w) / 2;
                if (clock_y <0) clock_y=0;
