            if (clock_y <0) { clock_y =0; rebound_dy = 1; }
            if (clock_x + total_w > max_x) { clock_x = max_x - total_w; if (clock_x<0) clock_x=0; rebound_dx = -1; }
            if (clock_y + total_h > max_y) { clock_y = max_y - total_h; if (clock_y<0) clock_y=0; rebound_dy = -1; }
        }

        // Get time
        time_t now = time(NULL);
        struct tm *tm;
        if (use_utc) tm = gmtime(&now);
        else tm = localtime(&now);

        // Handle blinking
        if (blinking) {
            // Toggle every 1 second? Or every draw? Original toggles every draw which is 1 sec
